#include <stdio.h>
#include <stdlib.h>
#include <zlib.h>

int restore(const char *src_path, const char *dst_path, size_t orig_len) {
  FILE *src = fopen(src_path, "rb");
  if (src == NULL) return -1;
  fseek(src, 0, SEEK_END);
  long src_len = ftell(src);
  rewind(src);
  unsigned char *in = malloc((size_t)src_len);
  unsigned char *out = malloc(orig_len);
  size_t got = in == NULL ? 0 : fread(in, 1, (size_t)src_len, src);
  fclose(src);
  uLongf out_len = (uLongf)orig_len;
  int rc = out == NULL || got != (size_t)src_len ? Z_MEM_ERROR : uncompress(out, &out_len, in, (uLong)src_len);
  free(in);
  if (rc != Z_OK) {
    free(out);
    return -1;
  }
  FILE *dst = fopen(dst_path, "wb");
  size_t put = dst == NULL ? 0 : fwrite(out, 1, out_len, dst);
  free(out);
  if (dst == NULL || fclose(dst) != 0 || put != out_len) return -1;
  return 0;
}

